#!/bin/bash
# Self-extracting updater for astro-endpoints.md docs (p2d2)
# Extrahiert: de/entwicklungshandbuch/api-referenz/astro-endpoints.md
#             en/entwicklungshandbuch/api-referenz/astro-endpoints.md
ARCHIVE_PAYLOAD_LINE=$(awk '/^__ARCHIVE_PAYLOAD_BELOW__/ {print NR + 1; exit 0}' "$0")
tail -n +$ARCHIVE_PAYLOAD_LINE "$0" | base64 -d | xz -d | tar -xvf -
exit 0

__ARCHIVE_PAYLOAD_BELOW__


